# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.41.0/ankra-cli-darwin-arm64"
      sha256 "8f1383014529ce7bf5abe1b40c96a20f59658c01d8f03395b6d257209c7e9c52"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.41.0/ankra-cli-darwin-amd64"
      sha256 "25f14f2b020d546b1a62be78735d9e8822dee5d57630db7ca32b931129b48652"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.41.0/ankra-cli-linux-arm64"
      sha256 "d9d448ca41e53ac6ebd76c8a376b40658b0b7d79fe5860d9a6971426b6cdaaef"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.41.0/ankra-cli-linux-amd64"
